out = []
t = date.fromisoformat(today)
for d in deployments:
    if d["mode"] == "local": out.append((d["name"], "local weights: not affected")); continue
    if d["api_id"] not in RETIREMENTS: out.append((d["name"], "no retirement scheduled")); continue
    when, repl = RETIREMENTS[d["api_id"]]
    days = (date.fromisoformat(when) - t).days
    if days < 0: out.append((d["name"], f"retired {when}: migrate to {repl}"))
    elif days <= warn_days: out.append((d["name"], f"retires in {days} days: plan move to {repl}"))
    else: out.append((d["name"], f"retires {when}"))
return out
